arguments.command:
chmod +x /app/check_cert.py && python3 /app/check_cert.py; echo "rc=$?"; python3 -c "
import sys;sys.modules['cryptography']=None" ; PYTHONPATH=/tmp/noc python3 - <<'EOF'
import builtins, runpy, sys
real=builtins.__import__
def imp(n,*a,**k):
    if n.startswith('cryptography'): raise ImportError('blocked')
    return real(n,*a,**k)
builtins.__import__=imp
try: runpy.run_path('/app/check_cert.py',run_name='__main__')
except SystemExit as e: print('fallback rc=',e.code)
EOF
openssl verify -CAfile /app/ssl/server.crt /app/ssl/server.crt; openssl rsa -in /app/ssl/server.pem -noout -check; openssl x509 -in /app/ssl/server.pem -noout -subject; ls -l /app/ssl

